-- Forward repair: PL/pgSQL client record shadowed the legacy receipt alias.
create or replace function public.iniciar_purga_residual_cliente_admin(p_cliente_id uuid) returns table(job_id uuid,bucket_id text,object_path text) language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); target public.clientes%rowtype; job public.residual_client_purge_jobs%rowtype;begin
 if actor is null or not public.tem_funcoes(array['admin'::public.tipo_funcao]) then raise exception using errcode='42501',message='USUARIO_NAO_AUTORIZADO';end if;select * into target from public.clientes where id=p_cliente_id for update;if not found then raise exception using errcode='P0002',message='CLIENTE_NAO_ENCONTRADO';end if;if target.usuario_id is not null or target.nome<>'Deleted customer' then raise exception using errcode='42501',message='EVIDENCIA_DE_ANONIMIZACAO_AUSENTE';end if;
 insert into public.residual_client_purge_jobs(client_id,actor_id,status)values(p_cliente_id,actor,'storage_pending')on conflict(client_id)do update set actor_id=excluded.actor_id,updated_at=now(),last_error=null where public.residual_client_purge_jobs.status<>'completed' returning * into job;if not found then select * into job from public.residual_client_purge_jobs where client_id=p_cliente_id;end if;
 insert into public.residual_client_purge_manifest(job_id,bucket_id,object_path)select job.id,'payment-proofs',key from public.payment_proofs proof cross join lateral unnest(array[proof.original_storage_key,proof.preview_storage_key]) key where proof.customer_id=p_cliente_id and key is not null union select job.id,'chat-midias',receipt.url_arquivo from public.comprovantes receipt where receipt.cliente_id=p_cliente_id and receipt.url_arquivo is not null on conflict do nothing;
 return query select m.job_id,m.bucket_id,m.object_path from public.residual_client_purge_manifest m where m.job_id=job.id and m.deleted_at is null order by m.bucket_id,m.object_path;end $$;
revoke all on function public.iniciar_purga_residual_cliente_admin(uuid) from public,anon,service_role;grant execute on function public.iniciar_purga_residual_cliente_admin(uuid) to authenticated;
